import copy, json, py_compile
from work import evaluate
req = {'declared':['b','a','a','skip'],'saved':{'a':{'kind':'file','meta':{'z':1,'x':2}},'b':{'kind':'missing'},'skip':{'kind':'file','hash':'old'},'extra':{'kind':'file','hash':'old'}},'current':{'a':{'meta':{'x':2,'z':1},'kind':'file'},'skip':{'kind':'file','hash':'new'},'extra':{'kind':'file','hash':'new'}}}
pol = {'ignored':['skip']}
r0, p0 = copy.deepcopy(req), copy.deepcopy(pol)
assert evaluate(req,pol) == {'needs_review':False,'changed':[]}
assert req == r0 and pol == p0
req2 = {'declared':['b','a','skip'],'saved':{'a':{'kind':'file','hash':'1'},'b':{'kind':'file','hash':'2'},'skip':{'kind':'file','hash':'x'}},'current':{'a':{'kind':'file','hash':'3'},'b':{'kind':'directory','entries':[]},'skip':{'kind':'file','hash':'y'}}}
